uttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw03={id="rw03",baseId="rwnpc14",combatid={2,100021},name="护卫",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL漕工：文本。NOR"}}},caozuoName2="询问",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw04={id="rw04",baseId="rwnpc27",combatid={2,100021},name="官员",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL官员：少侠可是收集到了确切的情报了？NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL官员：那就不奇怪了，果然是有内应相勾结。我这就派人去把他们拿下，审完他们，真相自然水落石出。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="doc",args={"CYN官员知会府兵出去抓人，不一会就把人带了回来。NOR"}},{type="addobject",args={"rw05"}},{type="addobject",args={"rw06"}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL官员：人已带到，少侠尽管审问。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL官员：若我没猜错，官府中与之勾结之人应该就是我的那个政敌，官府内的人好处理，可是这黑风寨，还真是有些麻烦。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL官员：我打算召集府兵与各路好汉，一同去那黑风寨走上一遭，想请少侠二人作为一支奇兵，不知少侠意下如何。NOR"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},caozuoName4="答应",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL官员：少侠愿意出手相助，在下感激不尽，我这就去召集人手，尽快出发。NOR"}},{type="delayer",args={2,"少侠稍安勿躁！"}},{type="gaintab",args={"318001",9}},{type="outgame",args={"hdfb1806"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",8}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw05={id="rw05",baseId="rwnpc10",combatid={2,100021},name="赵镖头",teamMark=-1,canSee=1,caozuoName1="审问",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL赵镖头：长期以来此地镖局都得自负盈亏，早就入不敷出，若是总镖局能多些支援，哪会沦落至此？官府中早就有人找到我，许以重利，希望能帮他们做掩护送走粮食。我要是不干还有其他人去干，我干了还能养活镖局上下几十号人，我也是无奈啊。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="审问",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL赵镖头：我都愿意交待，也愿意指认是何人指使，只求放我一条生路，别连累了镖局中的其他人。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw06={id="rw06",baseId="rwnpc09",combatid={2,100021},name="周掌柜",teamMark=-1,canSee=1,caozuoName1="偷听",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL周掌柜：就算是官府开仓放粮又能如何，能有多少粮食进得来呢？到头来不还是给我们做嫁衣。NOR"}},{type="delayer",args={1,"少侠稍安勿躁！"}},{type="doc",args={"YEL周掌柜：不必担心，此次的牵头人可不是我，而是上面那位大人，这粮食进出都早有人安排，镇内的粮食最多再维持个一两天，到那时就是我们发财的时候。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="偷听",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL周掌柜：放心吧，码头的漕运官是自己人，运粮的消息我们知道的一清二楚，还有赵镖头帮忙把镇内的粮食往外送。外面不还有黑风寨卡着粮道？这段时间就只有我们手上有粮，怕什么。NOR"}},{type="gaintab",args={"318001",6}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="偷听",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL周掌柜：喝酒喝酒，过几天就是我们赚大钱的时候。NOR"}}},caozuoName4="审问",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL周掌柜：冤枉啊，冤枉啊少侠，你说的江湖邪派我哪清楚，我这不也是道听途说的，别人都这样念叨我也就当真了。我毕竟是商人，也就只是囤个粮食低买高卖，这财路就是如此，没干违法的事啊。NOR"}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}},{type="gaintab",args={"318008",1}}},caozuoName5="审问",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL周掌柜：你你你，你这是从何得来的，怎么把我的字迹写的如此相像？少侠你要信我啊，是有人花了钱要我宣传此事和江湖邪派有关，估摸着也就是转移个视线，我不过是应了要求去宣传而已，怪我不得啊！NOR"}},{type="showbutton",args={6,1}}},caozuoName6="密信",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="puzzle",args={"40001"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"318001",7}},{type="equaltab",args={"318008",0}}}},autoResult1={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"318001",8}}}},autoResult2={{type="change",args={"rw06","rw12"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rw07={id="rw07",baseId="rwnpc39",combatid={2,100021},name="粮商",teamMark=-1,canSee=1,caozuoName1="偷听",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL粮商：说是强弩之末，谁又知道具体情况呢，唉，愁啊。NOR"}}},caozuoName2="宣扬消息",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCo